const fs=require('fs'),path=require('path'),assert=require('assert/strict'),crypto=require('crypto');
(async()=>{await(await fetch('http://127.0.0.1:8765/api/projects')).json();const url='http://127.0.0.1:8765/api/project?id=draft-7278d7c9-a753-4c98-bf8b-d7c2d45119ba',r=await fetch(url),raw=Buffer.from(await r.arrayBuffer()),p=JSON.parse(raw),before=structuredClone(p),source=JSON.parse(fs.readFileSync('备份/20261108-手部半格外描边-1794120965749/before.json')),dir=path.resolve('备份/20261108-撤销手部高清描边-'+Date.now());fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(dir+'/before.json',raw);fs.writeFileSync(dir+'/metadata.json',JSON.stringify({url,etag:r.headers.get('etag'),sha256:crypto.createHash('sha256').update(raw).digest('hex')}));let layers=0;for(const l of p.layers){if(!/^hand(?: 2)?(?: 描边)?$/.test(l.name))continue;const s=source.layers.find(x=>x.name===l.name&&x.sheetIndex===l.sheetIndex&&x.parent===l.parent);assert(s,'Original hand not found');l.frameData=structuredClone(s.frameData);layers++;}assert.equal(layers,48);assert.deepEqual(p.spriteSheets,before.spriteSheets);for(let i=0;i<p.layers.length;i++)if(!/^hand(?: 2)?(?: 描边)?$/.test(p.layers[i].name))assert.deepEqual(p.layers[i],before.layers[i]);fs.writeFileSync(dir+'/candidate.json',JSON.stringify(p));const put=await fetch(url,{method:'PUT',headers:{'Content-Type':'application/json','X-Pixel-Editor':'1','If-Match':r.headers.get('etag')},body:JSON.stringify(p)});const text=await put.text();assert(put.ok,'Save stopped '+put.status+' '+text);const saved=await(await fetch(url)).json();assert.deepEqual(saved,p);fs.writeFileSync(dir+'/verified.json',JSON.stringify(saved));fs.writeFileSync(dir+'/verification.json',JSON.stringify({layers,restoredOriginalHandResolution:true,skinColorsPreserved:true,eightLayersPreserved:true,canvasUnchanged:true,readback:'PASS'}));console.log(dir);})().catch(e=>{console.error(e);process.exitCode=1});
